#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Extract text snippets from RT-Stitching docx and emergency-decision pdf."""
import re, sys

def from_docx(path):
    import docx
    d = docx.Document(path)
    lines = []
    for p in d.paragraphs:
        t = p.text.strip()
        if t:
            lines.append(t)
    for tbl in d.tables:
        for row in tbl.rows:
            for cell in row.cells:
                t = cell.text.strip()
                if t:
                    lines.append(t)
    return "\n".join(lines)

def from_pdf(path):
    from pypdf import PdfReader
    r = PdfReader(path)
    out = []
    for pg in r.pages:
        try:
            out.append(pg.extract_text() or "")
        except Exception as e:
            out.append("")
    return "\n".join(out)

def show(name, text, keywords):
    print("=" * 30, name, "=" * 30)
    for kw in keywords:
        hits = []
        for m in re.finditer(re.escape(kw), text, re.IGNORECASE):
            s = max(0, m.start() - 90)
            e = min(len(text), m.end() + 120)
            hits.append(text[s:e].replace("\n", " "))
        if hits:
            print(f"--- [{kw}] ({len(hits)} hits) ---")
            for h in hits[:6]:
                print("   ", h[:220])
        else:
            print(f"--- [{kw}] (NO HIT) ---")

